type RequestProgressPanelProps = {
  request: SerializedNewsRequest;
  onRetry?: () => void;
  retrying?: boolean;
  progressPercent?: number;
  progressBusy?: boolean;
};

export function RequestProgressPanel({
  request,
  onRetry,
  retrying = false,
  progressPercent,
  progressBusy = false,
}: RequestProgressPanelProps) {
  if (request.status === "failed") {
    return (
      <Card size="sm" className="border-destructive/30">
        <CardHeader className="border-b pb-3">
          <CardTitle className="text-sm text-destructive">Request failed</CardTitle>
        </CardHeader>
        <CardContent className="flex flex-col gap-3 pt-4 text-sm">
          <p className="text-muted-foreground">
            {sanitizeNewsRequestError(request.error)}
          </p>
          {onRetry ? (
            <Button
              type="button"
              size="sm"
              variant="outline"
              disabled={retrying}
              onClick={onRetry}
            >
              {retrying ? "Retrying…" : "Try again"}
            </Button>
          ) : null}
        </CardContent>
      </Card>
    );
  }

  const isRerunning = request.isRerunning === true;
  const rounded = Math.round(progressPercent ?? 0);
  const showBar =
    progressBusy || request.status === "pending" || isRerunning;

  return (
    <Card size="sm">
      <CardHeader className="border-b pb-3">
        <CardTitle className="flex items-center gap-2 text-sm">
          {isRerunning ? "Refreshing briefing" : "Progress"}
          {progressBusy || isRerunning ? (
            <Spinner className="text-primary" />
          ) : null}
        </CardTitle>
      </CardHeader>
      <CardContent className="flex flex-col gap-4 pt-4">
        {showBar ? (
          <Progress value={rounded} className="w-full">
            <div className="flex w-full items-center gap-2">
              <ProgressLabel>
                {isRerunning ? "Refresh" : "Generating"}
              </ProgressLabel>
              {progressBusy || isRerunning ? (
                <Spinner className="text-accent" />
              ) : null}
              <ProgressValue />
            </div>
          </Progress>
        ) : null}
        {isRerunning ? (
          <LoadingLogLines
            loadingLogs={request.loadingLogs}
            busy={isRerunning}
          />
        ) : (
          <NewsRequestProgress
            loadingLogs={request.loadingLogs}
            status={request.status}
            isRerunning={isRerunning}
            title={
              request.status === "pending" || progressBusy
                ? "Progress"
                : "Your briefing"
            }
          />
        )}
      </CardContent>
    </Card>
  );
}
