/**
 * Stock research prompt enhancer — first step of the stock research pipeline.
 *
 * Rewrites the user's free-text research prompt into a clear, instrument-anchored
 * research brief (grammar, typos, explicit company/symbol) and lists the focus areas
 * the report should cover. Does not invent constraints (dates, price targets,
 * horizons) the user did not give.
 *
 * Model: `STOCK_RESEARCH_PROMPT_ENHANCER_MODEL` → `OPENAI_MODEL` → default.
 */

import {
  aiClient,
  createAIClient,
  type AIClientOptions,
} from "@/clients/AIClient";
import type { StockResearchInstrument } from "@/Agents/stockResearch/toolDeterminerAgent";
import { resolveOpenAiModelId } from "@/lib/openAiModel";
import { z } from "zod";

export const promptEnhancerOutputSchema = z.object({
  enhancedPrompt: z.string().min(1).max(2000),
  focusAreas: z.array(z.string().min(1).max(200)).max(8),
});

export type PromptEnhancerOutput = z.infer<typeof promptEnhancerOutputSchema>;

export type PromptEnhancerAgentParams = {
  userPrompt: string;
  instrument: StockResearchInstrument;
  model?: string;
  abortSignal?: AbortSignal;
};

export type PromptEnhancerResult = PromptEnhancerOutput & { model: string };

export function resolvePromptEnhancerModel(override?: string): string {
  return resolveOpenAiModelId(
    override,
    process.env.STOCK_RESEARCH_PROMPT_ENHANCER_MODEL,
  );
}

function buildSystemPrompt(): string {
  return [
    "You are a prompt enhancement agent for an Indian stock market research product.",
    "The user picked a specific instrument and wrote a research prompt about it.",
    "",
    "Rewrite the prompt into a clear, self-contained research brief:",
    "- Fix grammar, spelling and obvious typos in financial terminology.",
    "- Name the company and trading symbol explicitly (from the instrument context).",
    "- Keep every constraint the user gave (time horizon, risk appetite, metrics, comparisons) exactly.",
    "- Do NOT invent constraints the user did not give: no dates, years, price targets, horizons or position sizes.",
    "- If the prompt is vague (e.g. \"is it good?\"), frame it as a balanced investment research question about the instrument.",
    "- Do not answer the question or add facts.",
    "",
    "Also return 3–8 short focusAreas the final report should cover (e.g. \"valuation vs peers\", \"recent quarterly results\", \"promoter holding trend\"), derived from the prompt and the instrument type.",
  ].join("\n");
}

async function runPromptEnhancerCore(
  params: PromptEnhancerAgentParams,
  generate: typeof aiClient.generate,
): Promise<PromptEnhancerResult> {
  const model = resolvePromptEnhancerModel(params.model);
  const output = await generate({
    model,
    system: buildSystemPrompt(),
    prompt: params.userPrompt,
    extraContext: {
      instrument: {
        name: params.instrument.name,
        shortName: params.instrument.shortName,
        tradingSymbol: params.instrument.tradingSymbol,
        exchange: params.instrument.exchange,
        segment: params.instrument.segment,
        instrumentType: params.instrument.instrumentType,
      },
    },
    schemaName: "StockResearchPromptEnhancerOutput",
    schemaDescription: "Enhanced research brief plus report focus areas.",
    output: promptEnhancerOutputSchema,
    temperature: 0,
    maxOutputTokens: 1024,
    abortSignal: params.abortSignal,
  });

  return { ...output, model };
}

export function createPromptEnhancerAgent(options: AIClientOptions = {}) {
  const client = createAIClient(options);

  return async function promptEnhancerAgent(
    params: PromptEnhancerAgentParams,
  ): Promise<PromptEnhancerResult> {
    return await runPromptEnhancerCore(params, client.generate.bind(client));
  };
}

export async function runPromptEnhancerAgent(
  params: PromptEnhancerAgentParams,
): Promise<PromptEnhancerResult> {
  return await runPromptEnhancerCore(params, aiClient.generate.bind(aiClient));
}

/**
 * Stock research link selector — picks which normalized Serp links are worth
 * scraping with Firecrawl for the final report.
 *
 * Input: user prompt, enhanced prompt, instrument, normalized Serp hits (url, title,
 * snippet, source, date, engine) and optional AI overview / AI mode text.
 * Output: up to `maxLinks` hits (by candidate index) with a short reason each.
 * The model refers to candidates by index so it cannot return URLs that were not
 * in the Serp results.
 *
 * Model: `STOCK_RESEARCH_LINK_SELECTOR_MODEL` → `OPENAI_MODEL` → default.
 */

import {
  aiClient,
  createAIClient,
  type AIClientOptions,
} from "@/clients/AIClient";
import type { StockResearchInstrument } from "@/Agents/stockResearch/toolDeterminerAgent";
import { resolveOpenAiModelId } from "@/lib/openAiModel";
import type { NormalizedSerpHit } from "@/services/chat/normalizeSerpResults";
import { z } from "zod";

export const DEFAULT_MAX_SCRAPE_LINKS = 8;

const linkSelectorOutputSchema = z.object({
  selected: z
    .array(
      z.object({
        index: z.number().int().min(0),
        reason: z.string().min(1).max(300),
      }),
    )
    .max(20),
});

export type SelectedResearchLink = NormalizedSerpHit & { reason: string };

export type LinkSelectorAgentParams = {
  userPrompt: string;
  enhancedPrompt: string;
  instrument: StockResearchInstrument;
  links: NormalizedSerpHit[];
  /** AI overview / AI mode text from Serp, when present. */
  serpSummaries?: string[];
  maxLinks?: number;
  model?: string;
  abortSignal?: AbortSignal;
};

export function resolveLinkSelectorModel(override?: string): string {
  return resolveOpenAiModelId(
    override,
    process.env.STOCK_RESEARCH_LINK_SELECTOR_MODEL,
  );
}

function buildSystemPrompt(maxLinks: number): string {
  return [
    "You select web pages to scrape for an investment research report on one listed instrument.",
    `Pick at most ${maxLinks} candidates whose full text will add the most to answering the research brief.`,
    "",
    "Prefer:",
    "- Pages specifically about this company/instrument (not generic market wraps or other companies).",
    "- Recent results coverage, earnings call notes, management commentary, analyst/broker views, regulatory filings, credible business press.",
    "- Distinct angles: avoid several pages repeating the same news item.",
    "",
    "Avoid:",
    "- Quote-only pages, stock-tip / buy-sell-call pages, forums, social media, video pages, login/paywall-only pages.",
    "- Pages about a different company with a similar name.",
    "",
    "Return candidates by their `index` field, with a one-line reason each. Return fewer than the maximum if few candidates are relevant.",
  ].join("\n");
}

async function runLinkSelectorCore(
  params: LinkSelectorAgentParams,
  generate: typeof aiClient.generate,
): Promise<SelectedResearchLink[]> {
  if (params.links.length === 0) {
    return [];
  }

  const maxLinks = params.maxLinks ?? DEFAULT_MAX_SCRAPE_LINKS;
  const candidates = params.links.map((link, index) => ({
    index,
    url: link.url,
    title: link.title ?? null,
    snippet: link.snippet ?? null,
    source: link.source ?? null,
    date: link.date ?? null,
    engine: link.engine,
  }));

  const output = await generate({
    model: resolveLinkSelectorModel(params.model),
    system: buildSystemPrompt(maxLinks),
    prompt: params.enhancedPrompt,
    extraContext: {
      originalUserPrompt: params.userPrompt,
      instrument: {
        name: params.instrument.name,
        tradingSymbol: params.instrument.tradingSymbol,
        exchange: params.instrument.exchange,
        instrumentType: params.instrument.instrumentType,
      },
      serpSummaries: params.serpSummaries ?? [],
      candidates,
    },
    schemaName: "StockResearchLinkSelectorOutput",
    schemaDescription: "Indexes of candidate links to scrape, with reasons.",
    output: linkSelectorOutputSchema,
    temperature: 0,
    maxOutputTokens: 2048,
    abortSignal: params.abortSignal,
  });

  const seen = new Set<number>();
  const selected: SelectedResearchLink[] = [];
  for (const row of output.selected) {
    const link = params.links[row.index];
    if (!link || seen.has(row.index)) {
      continue;
    }
    seen.add(row.index);
    selected.push({ ...link, reason: row.reason });
    if (selected.length >= maxLinks) {
      break;
    }
  }
  return selected;
}

export function createLinkSelectorAgent(options: AIClientOptions = {}) {
  const client = createAIClient(options);

  return async function linkSelectorAgent(
    params: LinkSelectorAgentParams,
  ): Promise<SelectedResearchLink[]> {
    return await runLinkSelectorCore(params, client.generate.bind(client));
  };
}

export async function runLinkSelectorAgent(
  params: LinkSelectorAgentParams,
): Promise<SelectedResearchLink[]> {
  return await runLinkSelectorCore(params, aiClient.generate.bind(aiClient));
}

/**
 * Stock research report synthesizer — final step of the stock research pipeline.
 *
 * Turns collected Upstox market/fundamental data, Firecrawl-scraped web pages and
 * Serp summaries into one Markdown research report answering the (enhanced) user
 * prompt. Every web-derived claim links to its source URL; numbers come only from
 * the supplied data.
 *
 * Model: `STOCK_RESEARCH_SYNTHESIZER_MODEL` → default `gpt-5.4-mini`.
 */

import {
  aiClient,
  createAIClient,
  type AIClientOptions,
} from "@/clients/AIClient";
import type { StockResearchInstrument } from "@/Agents/stockResearch/toolDeterminerAgent";
import { resolveOpenAiModelId } from "@/lib/openAiModel";
import { z } from "zod";

const DEFAULT_STOCK_RESEARCH_SYNTHESIZER_MODEL = "gpt-5.4-mini";

const reportSynthesizerOutputSchema = z.object({
  markdown: z.string().min(1),
});

export type ReportSynthesizerUpstoxInput = {
  tool: string;
  /** Compacted JSON text of the tool response. */
  data: string;
};

export type ReportSynthesizerWebPageInput = {
  url: string;
  title: string | null;
  source: string | null;
  date: string | null;
  content: string;
};

export type ReportSynthesizerAgentParams = {
  userPrompt: string;
  enhancedPrompt: string;
  focusAreas: string[];
  instrument: StockResearchInstrument;
  upstoxData: ReportSynthesizerUpstoxInput[];
  webPages: ReportSynthesizerWebPageInput[];
  serpSummaries: string[];
  /** Tools that were planned but failed, so the report can note data gaps. */
  unavailableTools: string[];
  model?: string;
  abortSignal?: AbortSignal;
};

export type ReportSynthesizerResult = { markdown: string; model: string };

export function resolveReportSynthesizerModel(override?: string): string {
  return resolveOpenAiModelId(
    override,
    process.env.STOCK_RESEARCH_SYNTHESIZER_MODEL ??
      DEFAULT_STOCK_RESEARCH_SYNTHESIZER_MODEL,
  );
}

function buildSystemPrompt(): string {
  return [
    "You are an equity research analyst writing for Indian retail investors.",
    "Write one Markdown research report on the given instrument that answers the research brief.",
    "",
    "Sources you may use (and nothing else):",
    "- upstoxData: market quotes, candles, fundamentals, shareholding, corporate actions, derivatives analytics, FII/DII flows (JSON, possibly truncated).",
    "- webPages: scraped article text, each with a url.",
    "- serpSummaries: search engine AI summaries — treat as leads, not facts, unless a webPage or upstoxData confirms them.",
    "",
    "Rules:",
    "- Every number must come from the supplied data. Never invent prices, ratios, dates or targets.",
    "- Cite web-derived claims inline as Markdown links to the page url, e.g. ([Economic Times](https://...)).",
    "- When data is missing or a tool is listed in unavailableTools, say so briefly instead of guessing.",
    "- Present both bull and bear points; do not give a personalised buy/sell instruction.",
    "- Use Indian number formatting conventions (₹, lakh, crore) where natural.",
    "",
    "Structure (skip a section when there is no data for it):",
    "# <Company> (<SYMBOL>) — <short title reflecting the brief>",
    "## Summary — 3–5 bullet answer to the brief",
    "## Price & trading snapshot — table of key quote/OHLC/52-week figures",
    "## Business & fundamentals — profile, key ratios, financial statement trends (tables welcome)",
    "## Ownership & flows — shareholding pattern, FII/DII context",
    "## Recent news & developments — dated, cited",
    "## Derivatives view — only for F&O instruments or when option data exists",
    "## Risks",
    "## Bull vs bear case",
    "## Sources — bullet list of the web page links used",
    "",
    "End with one italic line: research summary, not investment advice.",
    "Return only the Markdown in the `markdown` field.",
  ].join("\n");
}

async function runReportSynthesizerCore(
  params: ReportSynthesizerAgentParams,
  generate: typeof aiClient.generate,
): Promise<ReportSynthesizerResult> {
  const model = resolveReportSynthesizerModel(params.model);
  const output = await generate({
    model,
    system: buildSystemPrompt(),
    prompt: params.enhancedPrompt,
    extraContext: {
      originalUserPrompt: params.userPrompt,
      focusAreas: params.focusAreas,
      instrument: params.instrument,
      upstoxData: params.upstoxData,
      webPages: params.webPages,
      serpSummaries: params.serpSummaries,
      unavailableTools: params.unavailableTools,
    },
    schemaName: "StockResearchReportOutput",
    schemaDescription: "Markdown research report.",
    output: reportSynthesizerOutputSchema,
    maxOutputTokens: 16_000,
    abortSignal: params.abortSignal,
  });

  return { markdown: output.markdown.trim(), model };
}

export function createReportSynthesizerAgent(options: AIClientOptions = {}) {
  const client = createAIClient(options);

  return async function reportSynthesizerAgent(
    params: ReportSynthesizerAgentParams,
  ): Promise<ReportSynthesizerResult> {
    return await runReportSynthesizerCore(params, client.generate.bind(client));
  };
}

export async function runReportSynthesizerAgent(
  params: ReportSynthesizerAgentParams,
): Promise<ReportSynthesizerResult> {
  return await runReportSynthesizerCore(params, aiClient.generate.bind(aiClient));
}

