                              {source.source ?? hostLabel(source.url!)}
                            </span>
                          </span>
                        </a>
                      </li>
                    ))}
                  </ul>
                ) : null}
                {dataTools.length > 0 ? (
                  <div className="flex flex-wrap gap-1.5">
                    {dataTools.map((tool) => (
                      <Badge key={tool} variant="outline">
                        Upstox · {tool}
