function titleTokens(title: string | undefined): Set<string> {
  return new Set(
    (title ?? "")
      .toLowerCase()
      .replace(/[^a-z0-9\\s]/g, " ")
      .split(/\\s+/)
      .filter((token) => token.length >= 3),
