async function main() {
  const scope = (process.argv[2] ?? "world") as any;
  const location = process.argv[3] ?? (scope === "world" ? null : "India");
  const config = normalizeNewsGenerationRequest({ date: new Date().toISOString().slice(0, 10), scope, ...(location ? { location } : {}), storyCount: 5 });
  const T: Record<string, number> = {}; const t0 = Date.now(); let t = t0;
  const lap = (k: string) => { T[k] = Date.now() - t; t = Date.now(); };
  const F: [string, number, string?][] = [];

  const executionPlans = buildNewsSearchExecutionPlans(config), topicPlans = buildNewsTopicSearchPlans(config);
  const serpNum = serpResultsPerEngine(config.storyCount);
  const v = <T,>(r: PromiseSettledResult<T>) => (r.status === "fulfilled" ? r.value : null);
