    Promise.all(topicPlans.map(async (plan) => { const [news, search] = await Promise.all([within(serpEngines.searchGoogleNews.fn(plan.googleNewsParams), 15000), within(serpEngines.searchGoogle.fn({ ...plan.googleSearchParams, num: serpNum }), 15000)]); return { news, search }; })),
  ]);
  const googleNewsPayload = interleaveSerpPayloads([...tierResults.map((r) => r.news), ...topicResults.map((r) => r.news)]);
  const googleSearchPayload = interleaveSerpPayloads([...tierResults.map((r) => r.search), ...topicResults.map((r) => r.search)]);
  let merged: unknown = googleSearchPayload; let followUps: unknown[] = [];
  const primaryPlan = executionPlans[0]!;
  if (serpPayloadHasAiOverview(googleSearchPayload)) {
    const text = extractAiOverviewTextFromSerpPayload(googleSearchPayload);
    if (text) {
      const gen = await runGaiOverviewSearchGeneratorAgent({ aiOverviewText: text, date: config.date, location: config.location ?? undefined, scope: config.scope === "both" ? "world" : config.scope, abortSignal: AbortSignal.timeout(120000) });
      const gl = primaryPlan.news.suggestedGl ?? primaryPlan.search.suggestedGl;
