  lap("discover");

  const researchPrompt = buildArticleSelectionPrompt(config);
  const candidateBudget = articleCandidateBudget(config.storyCount), scrapeBudget = maxArticlesToScrape(config.storyCount);
  const budgeted = preferArticlesFromSources(excludeTradingRecommendationArticles(normalized), config.sources).slice(0, candidateBudget);
  const pickedRaw = await runResearchArticleSelectorAgent({ userPrompt: researchPrompt, links: budgeted.map((a) => ({ url: a.url, title: a.title, snippet: a.snippet, source: a.source, sourceType: a.sourceType, selectionWeight: a.selectionWeight, fromAiOverviewFollowUp: a.fromAiOverviewFollowUp })), topPercent: 50, abortSignal: AbortSignal.timeout(180000) });
  const selected = pickedRaw.filter((a) => !isTradingRecommendationArticle({ title: a.title })).slice(0, scrapeBudget);
  F.push(["ai-eval candidates", budgeted.length, `budget=${candidateBudget}`], ["ai-eval passed (relevant, top 50%)", pickedRaw.length], ["shortlisted-for-firecrawl", selected.length, `cap=${scrapeBudget}`]);
